const KEY='projectgate-v1';
const initial=()=>({role:'Team Lead',student:0,stage:0,unlocked:true,status0:'Draft',status1:'Draft',status2:'Draft',status3:'Draft',feedback:'',score:8,repo:'https://github.com/topics/timetable-scheduling',members:[{name:'Parth Karpe',usn:'01FE23BCS101',role:'Team Lead · Full-stack',github:'https://github.com',skills:'Frontend, integration',contribution:'Dashboard design and application integration.'},{name:'Nupur Bagave',usn:'01FE23BCS102',role:'Algorithm Developer',github:'https://github.com',skills:'Python, optimization',contribution:'Constraint modeling and scheduling algorithm.'},{name:'Vedant Khot',usn:'01FE23BCS103',role:'Backend Developer',github:'https://github.com',skills:'APIs, database',contribution:'Data model, API design and validation.'},{name:'Sachi Aarati',usn:'01FE23BCS104',role:'Research & Testing',github:'https://github.com',skills:'Research, testing',contribution:'Literature review and evaluation experiments.'}],forms:{0:{title:'Adaptive Academic Timetable Optimization',problem:'Manual timetable creation is time-consuming and causes faculty, room and student scheduling conflicts.',objectives:'Generate conflict-free timetables; reduce scheduling effort; respect faculty availability and room capacities.',users:'Department coordinators, faculty members and students.',baseline:'Compared manual scheduling with constraint satisfaction and genetic algorithm approaches. Hard constraints must always be satisfied; soft preferences guide optimization.',scope:'In-Scope: Single department automated timetable generation with room and faculty scheduling.\nOut-of-Scope: University-wide multi-campus bus transportation scheduling.',courses:'DAA (Optimization algorithms), OS (Concurrency & scheduling), SE (Requirements & architecture).',engines:'E1: Constraint Formulation Engine, E2: Timetable Conflict Solver Engine, E3: Web Verification Dashboard.'},1:{functional:'FR-01: Ingestion of faculty, courses, and room inventory. FR-02: Automated conflict-free timetable generation. FR-03: Export schedule to PDF and CSV.',nonfunctional:'NFR-01: Zero hard-constraint conflicts. NFR-02: Schedule generation in < 30 seconds for 120 slots. NFR-03: Role-based coordinator access control.',architecture:'Web presentation dashboard → REST API router → Constraint Satisfaction Solver engine → IndexedDB & LocalStorage persistence.',workflow:'Phase 01: Ingestion → Phase 02: Constraint formulation → Phase 03: Solver iteration → Phase 04: Visual verification & export.',techstack:'Frontend: HTML5, CSS3, Vanilla JS ES2022. Solver: Python 3.11 with OR-Tools constraint satisfaction engine. Storage: LocalStorage and Browser IndexedDB.',constraints:'Runs on standard commodity hardware with minimum 4GB RAM. Operates offline without external cloud dependency.'},2:{implementation:'Constraint Satisfaction Problem (CSP) formulation modeling time slots as variables, faculty availability and room capacities as hard constraints, and preferred periods as soft objective penalties.',modules:'1. TimetableParser, 2. ConstraintFormulator, 3. CSPBacktrackingSolver, 4. ConflictDetector, 5. ScheduleExporter.',repo:'https://github.com/topics/timetable-scheduling',challenges:'Handling sudden faculty unavailability requires dynamic localized re-scheduling without recalculating the entire semester timetable.'},3:{testing:'Acceptance test suite asserting zero faculty double-booking, zero room overcapacity, and 100% curriculum slot coverage.',test_results:'REQ-01 (Faculty non-overlap): PASS (0 conflicts across 180 slots). REQ-02 (Room capacity): PASS. REQ-03 (Generation time): PASS in 4.2 seconds.',metrics:'Generation Latency: 4.2s (Target: < 30s) · Conflict Rate: 0.0% (Target: 0.0%) · Faculty Preference Satisfaction: 91.4%.',evaluation:'The constraint engine consistently produces zero-conflict schedules. Future work will incorporate multi-objective genetic algorithms for student elective load balancing.'}},questions:[],answers:{},activities:[{text:'Team portfolio created',time:'Sample activity'},{text:'Stage 0 draft prepared',time:'Sample activity'}],ollama:{url:'http://localhost:11434',model:'qwen3:4b'},mode:'demo'});
let state;try{state=JSON.parse(localStorage.getItem(KEY))||initial()}catch{state=initial()}let page='Overview',modal=null;try{const sp=sessionStorage.getItem('pg_current_page');if(sp)page=sp;}catch(e){}
